import java.util.*;
class Main {
  public static void main(String[] args) {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put("b", 2);
    m.put("a", 1);
    for (String k : m.keySet()) System.out.print(k);
    System.out.println();
  }
}

